$search=trim($_GET['search']??'');$filter=$_GET['kind']??'';$where='r.certificate_number IS NOT NULL';$params=[];
if($search!=='') {$where.=' AND (r.certificate_number LIKE ? OR r.name LIKE ? OR p.title LIKE ?)';$params=['%'.$search.'%','%'.$search.'%','%'.$search.'%'];}
if(isset($eventTypes[$filter])) {$where.=' AND p.event_type=?';$params[]=$filter;}
$total=(int)rows('SELECT COUNT(*) n FROM recipients r JOIN projects p ON p.id=r.project_id WHERE '.$where,$params)[0]['n'];
$pages=max(1,(int)ceil($total/50));$pageNo=max(1,min($pages,(int)($_GET['p']??1)));$offset=($pageNo-1)*50;
$records=rows('SELECT r.*,p.title,p.event_type,p.published FROM recipients r JOIN projects p ON p.id=r.project_id WHERE '.$where.' ORDER BY r.id DESC LIMIT 50 OFFSET '.$offset,$params);
?>
